package com.bank.pkvi.repository;

import com.bank.pkvi.model.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.List;
import java.util.Optional;

public interface AccountRepository extends JpaRepository<Account, String> {
    // PRIMARY KEY lookup: identity, at most one row (findById is inherited)
    // Plain INDEX lookup: many accounts per branch, duplicates expected
    List<Account> findByBranchCode(String branchCode);
    // UNIQUE INDEX lookup: natural key, at most one row, but not the identity
    Optional<Account> findByPan(String pan);
}
