package com.bank.pkvi.service;

import com.bank.pkvi.model.Account;
import com.bank.pkvi.repository.AccountRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;
import java.util.Optional;

@Service
public class AccountService {
    private static final Logger log = LoggerFactory.getLogger(AccountService.class);
    private final AccountRepository repo;

    public AccountService(AccountRepository repo) { this.repo = repo; }

    public Optional<Account> byIdentity(String id) {
        log.info("PRIMARY KEY lookup {}: constraint-backed identity, unique + not null", id);
        return repo.findById(id);
    }

    public List<Account> byBranch(String branch) {
        log.info("Plain INDEX lookup branch {}: duplicates allowed, no rule enforced", branch);
        return repo.findByBranchCode(branch);
    }

    public Optional<Account> byPan(String pan) {
        log.info("UNIQUE INDEX lookup PAN: enforces uniqueness but is NOT the identity");
        return repo.findByPan(pan);
    }
}
